import{z as A,x as p,o as t,c as B,q as i,j as s,D as E,d as l,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"掩模台同步","description":"","frontmatter":{"title":"掩模台同步","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reticle-stage-sync.md","filePath":"litho/reticle-stage-sync.md","lastUpdated":1791413859000}'),d={name:"litho/reticle-stage-sync.md"};function h(m,a,D,C,c,u){const r=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=i('<h1 id="掩模台同步" tabindex="-1">掩模台同步 <a class="header-anchor" href="#掩模台同步" aria-label="Permalink to &quot;掩模台同步&quot;">​</a></h1><div class="epigraph"><p>扫描曝光不是晶圆台独自匀速走过狭缝；掩模必须以光学倍率锁住同一条轨迹，同步误差同时变成套刻与有效离焦。</p><footer>—— 对照 ASML 对 TWINSCAN 双工件台与扫描同步的公开说明</footer></div><p><a href="/litho/euv-maglev-stage">上一课</a>把真空里的支承写成磁浮：气浮被取消，硅片台与掩模台都靠洛伦兹力做六自由度。缺口是两者如何锁在一起。扫描机的像是狭缝里积分出来的，掩模台速度必须按倍率跟上晶圆台，相位误差进 overlay，速度抖动进剂量。双工件台还要求同一套掩模台在交换后立刻锁到另一张晶圆台上。本课钉掩模台同步。随机效应如何把欠剂量写成缺陷，留给后课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投影倍率把掩模平面与硅片平面绑成一对相似运动。0.33 系统约 4×：掩模台扫描速度约为晶圆台的四倍。<a href="/litho/asml-high-na">High-NA</a> 变形光学在狭缝向仍约 4×、扫描向约 8×，同步合同按方向拆开，不能再用各向同性 4× 的口令。位置环误差在硅片坐标里就是套刻；速度环误差改变狭缝停留时间，变成 CD。</p><p><span class="marginnote">数字实例：晶圆台以约 500 mm/s 扫过 33 mm 场约需 66 ms；同一时刻 NXE 的掩模台要跑约 4×，即 2000 mm/s，High-NA 在 8× 方向要等效约 4000 mm/s。掩模台是全机最快的宏观运动部件之一，误差却按纳米结账。</span></p><p>双工件台（TWINSCAN 公开架构）并行的是两张<strong>晶圆</strong>台：一台曝光、一台测量。光学与掩模台仍是一套。交换之后，掩模台必须对新卡盘的网格、高度图和扫描起点重新同步，而不能假设「磁浮已经够准就自然对齐」。缺口是同步伺服与倍率几何，不是再讲一遍失浮安全。</p><h3 id="双台不是双掩模台" tabindex="-1">双台不是双掩模台 <a class="header-anchor" href="#双台不是双掩模台" aria-label="Permalink to &quot;双台不是双掩模台&quot;">​</a></h3><p>把 dual stage 理解成两套完整扫描机，会把掩模台的动态预算算错。曝光位在换卡盘，掩模台要加速、建立、锁相，建立时间直接吃产能。加速度越大，反力越容易打进物镜；同步带宽越高，计量环的热与振动越不能装糊涂。问题因此是：在一套掩模台上，对交替进入的两张晶圆台保持纳米级扫描锁相。</p><p><span class="marginnote">「同步」在产线口语里有时被说成对准。对准是曝光前读标记、建网格；同步是曝光中掩模与晶圆相对速度/位置的实时锁。本课对象是后者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>控制上把扫描轨迹写成时间的函数：晶圆台按场长与剂量决定 \\(v_\\mathrm{w}\\)，掩模台 \\(v_\\mathrm{r}=M\\,v_\\mathrm{w}\\)（\\(M\\) 为该方向倍率），再叠加畸变、热与掩模变形的前馈。位置计量用编码器或干涉仪，闭环把跟踪误差压进套刻与剂量预算。源功率与台速度互锁：功率跌则减速，避免欠剂量条纹——上一课已把这条写在硅片台上，本课补上：减速必须掩模台同时减速，否则倍率锁被自己打断。</p><p><span class="marginnote">直觉类比：双人三足赛跑，两条腿必须按固定比例迈步。晶圆台与掩模台就是那两条腿，倍率 \\(M\\) 是「步频比」；一方突然放慢而另一方没跟上，轻则步幅错位（套刻条纹），重则摔倒（撞版）。</span></p><p>High-NA 半场更短，加速段占场长的比例变大，建立时间更金贵。Z 向调焦在薄<a href="/litho/high-na-resist-budget">胶厚预算</a>下更严，Rx/Ry 调平与扫描同步是同一套短行程自由度上的不同轴，不能把 XY 锁相做好就宣布同步完成。</p><h3 id="交换之后的锁相" tabindex="-1">交换之后的锁相 <a class="header-anchor" href="#交换之后的锁相" aria-label="Permalink to &quot;交换之后的锁相&quot;">​</a></h3><p>卡盘指纹、夹持变形、上一场留下的热，都让「同一条扫描公式」在两张台上并不相同。产线用匹配套刻与 dedicated chuck 策略来承认这件事。公开叙事能写到的是：双台提高的是测量与曝光的重叠，掩模台是共享资源，同步规格必须按较差的那张卡盘来写。</p>',16)),(t(),s(o,null,{default:E(()=>[n(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20JOB%5B%22%E5%9C%BA%E9%95%BF%20%C3%97%20%E5%89%82%E9%87%8F%20%E2%86%92%20%E8%AE%BE%E5%AE%9A%20vw%22%5D%20--%3E%20MLOCK%7B%22%E5%80%8D%E7%8E%87%E9%94%81%3A%20vr%20%3D%20M%2C%20%E6%8C%89%E6%96%B9%E5%90%91%22%7D%0A%20%20MLOCK%20--%3E%20XDIR%5B%22%E7%8B%AD%E7%BC%9D%E5%90%91%20M%20%E2%89%88%204x%22%5D%0A%20%20MLOCK%20--%3E%20YDIR%5B%22%E6%89%AB%E6%8F%8F%E5%90%91%20M%20%E2%89%88%208x%20(High-NA)%22%5D%0A%20%20DIP%5B%22%E6%BA%90%E5%8A%9F%E7%8E%87%E8%B7%8C%E8%90%BD%22%5D%20--%3E%20DEC%5B%22%E4%BA%92%E9%94%81%E5%87%8F%E9%80%9F%22%5D%0A%20%20DEC%20--%3E%20BOTH%5B%22vw%20%E4%B8%8E%20vr%20%E5%90%8C%E6%97%B6%E4%B8%8B%E9%99%8D%22%5D%0A%20%20BOTH%20--%3E%20SAFE%5B%22%E5%89%82%E9%87%8F%E4%BF%9D%E6%8C%81%2C%20%E9%94%81%E4%B8%8D%E7%A0%B4%22%5D%0A%20%20DEC%20--%3E%20HALF%5B%22%E5%8F%AA%E5%87%8F%E4%B8%80%E4%BE%A7%20%E2%86%92%20%E7%9B%B8%E5%AF%B9%E9%80%9F%E5%BA%A6%E5%A4%B1%E9%94%81%22%5D%0A%20%20HALF%20--%3E%20STRIPE%5B%22%E6%89%AB%E6%8F%8F%E5%90%91%E6%AC%A0%E5%89%82%E9%87%8F%E6%9D%A1%E7%BA%B9%20%2F%20%E5%A5%97%E5%88%BB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"狭缝在硅片上扫过时，每一点的空中像是掩模对应狭缝的瞬时像。若掩模超前或滞后 \\(\\delta x_\\mathrm{r}\\)，硅片上等效位移约 \\(\\delta x_\\mathrm{r}/M\\)，进 overlay。若相对速度比偏离 \\(M\\)，狭缝积分的有效曝光时间沿扫描向变化，CD 出现条纹。离焦通道：同步不好时两台的瞬时物像共轭被破坏，等效于局部 \\(z\\) 误差，在薄焦深里与胶厚预算叠加。",-1)),a[5]||(a[5]=e("p",null,"计量光路在真空里仍可能用非 EUV 波长，残余气体折射率进误差模型。掩模侧还有 pellicle 质量与热引起的平衡变化，载荷虽小于晶圆台，速度更高，动态更狠。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"ASML 不会公开伺服增益。可写的是倍率锁、速度–剂量互锁、双晶圆台共享一套掩模台。不要把专利里的磁钢排列写成教材里的「标准参数」。")],-1)),(t(),s(o,null,{default:E(()=>[n(r,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E6%99%B6%E5%9C%86%E5%8F%B0%E6%89%AB%E6%8F%8F%20vw%22%5D%20--%3E%20LOCK%5B%22%E5%80%8D%E7%8E%87%E9%94%81%E7%9B%B8%22%5D%0A%20%20R%5B%22%E6%8E%A9%E6%A8%A1%E5%8F%B0%20vr%20%3D%20M%20vw%22%5D%20--%3E%20LOCK%0A%20%20LOCK%20--%3E%20OV%5B%22%E4%BD%8D%E7%BD%AE%E8%AF%AF%E5%B7%AE%20%E2%86%92%20%E5%A5%97%E5%88%BB%22%5D%0A%20%20LOCK%20--%3E%20CD%5B%22%E9%80%9F%E5%BA%A6%E8%AF%AF%E5%B7%AE%20%E2%86%92%20%E5%89%82%E9%87%8F%20%2F%20CD%22%5D%0A%20%20SWAP%5B%22%E5%8F%8C%E5%8F%B0%E4%BA%A4%E6%8D%A2%22%5D%20--%3E%20LOCK%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>同步不增加 NA，不增加光子数。它只让扫描投影在套刻与剂量上成立。为产能把速度拉满，随机缺陷会先报警，那是后课的剂量账，不是再加一级掩模台加速度能消灭的。单工件台研发工具可以弱化双台交换，HVM 的 NXE/EXE 公开叙事仍是双晶圆台加同步扫描。pellicle 的质量与热会进掩模台平衡，同步规格要把膜架当作载荷的一部分，而不是只按裸版写。</p><p>后课默认：说到扫描同步，已经包含掩模台与晶圆台按倍率锁相，而不是只有硅片台磁浮。</p><p>pellicle 框架的热漂移若未进前馈，会在长曝光里表现为扫描向缓变套刻，看起来像「台子在爬」。</p><p><span class="marginnote">评价同步要同时看套刻残差与扫描向 CD 均匀性。只报静态 overlay、不报扫描中的速度噪声，等于只报停车精度。</span></p><p><span class="marginnote">常见误区：把双工件台听成两套掩模台。并行的只是两张晶圆台（一台曝光、一台测量），掩模台始终只有一套、来回伺候两张台——它的同步预算要按「最差的那张卡盘」写，不是按平均。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扫描曝光要求掩模台与晶圆台按光学倍率锁相，误差进套刻与剂量。</li><li>TWINSCAN 双台并行的是两张晶圆台；掩模台是共享的同步对象。</li><li>High-NA 变形倍率让两个方向的 \\(M\\) 不同，同步合同必须按轴拆开。</li><li>源功率与速度互锁必须两岸同时执行，否则自己打断倍率锁。</li><li>出处：ASML 关于 TWINSCAN 双工件台与扫描扫描机的公开说明。</li></ul>',8))])}const f=A(d,[["render",h]]);export{g as __pageData,f as default};
